CREATE OR REPLACE FUNCTION public.guard_rider_support_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_any_role(auth.uid(), ARRAY['admin','support','super_admin']::public.app_role[]) THEN IF NEW.assigned_agent_id IS NOT NULL OR NEW.assigned_at IS NOT NULL THEN RAISE EXCEPTION 'Riders cannot choose a support agent'; END IF; END IF; RETURN NEW; END; $$; REVOKE ALL ON FUNCTION public.guard_rider_support_insert() FROM PUBLIC, anon, authenticated; CREATE TRIGGER trg_support_threads_a_guard BEFORE INSERT ON public.support_threads FOR EACH ROW EXECUTE FUNCTION public.guard_rider_support_insert(); DROP POLICY "Riders open own support threads" ON public.support_threads; CREATE POLICY "Riders open own support threads" ON public.support_threads FOR INSERT TO authenticated WITH CHECK (rider_user_id = auth.uid() AND created_by = auth.uid() AND rider_email = lower(auth.jwt() ->> 'email') AND status = 'open');